152: 	}, func(_ context.Context, _ *mcp.CallToolRequest, in orderInput) (*mcp.CallToolResult, any, error) {
153: 		v, err := c.Order(project, in.Text)
154: 		if err != nil {
155: 			return errorResult(err)
156: 		}
157: 		return jsonResult(v)
158: 	})
159: 
160: 	mcp.AddTool(s, &mcp.Tool{
161: 		Name:        "pending",
162: 		Description: "Return the question the session is waiting on, if any.",
163: 	}, func(_ context.Context, _ *mcp.CallToolRequest, _ Empty) (*mcp.CallToolResult, any, error) {
164: 		q, err := c.Pending(project)
