166: 			return errorResult(err)
167: 		}
168: 		return jsonResult(questionView{Question: q})
169: 	})
170: 
171: 	mcp.AddTool(s, &mcp.Tool{
172: 		Name:        "answer",
173: 		Description: "Answer the pending question with one of its options.",
174: 	}, func(_ context.Context, _ *mcp.CallToolRequest, in answerInput) (*mcp.CallToolResult, any, error) {
175: 		if err := c.Answer(project, in.Option); err != nil {
176: 			return errorResult(err)
177: 		}
178: 		return jsonResult(okView{OK: true})
179: 	})
180: 
181: 	mcp.AddTool(s, &mcp.Tool{
182: 		Name:        "interrupt",
