202: 	mcp.AddTool(s, &mcp.Tool{
203: 		Name:        "restart",
204: 		Description: "Restart the session, optionally forcing it.",
205: 	}, func(_ context.Context, _ *mcp.CallToolRequest, in restartInput) (*mcp.CallToolResult, any, error) {
206: 		if err := c.Restart(project, in.Force); err != nil {
