208: 		}
209: 		return jsonResult(okView{OK: true})
210: 	})
211: 
212: 	mcp.AddTool(s, &mcp.Tool{
213: 		Name:        "plan_load",
214: 		Description: "Load the approved plan and its phases into the queue.",
215: 	}, func(_ context.Context, _ *mcp.CallToolRequest, in planLoadInput) (*mcp.CallToolResult, any, error) {
216: 		plan := queue.Plan{Approved: in.Approved}
217: 		for _, p := range in.Phases {
218: 			phase := queue.Phase{ID: p.ID, StopAfter: p.StopAfter}
219: 			if p.Caps != nil {
220: 				phase.Caps = queue.Caps{
221: 					ClaudeUSD:   p.Caps.ClaudeUSD,
222: 					Hours:       p.Caps.Hours,
223: 					ExecutorUSD: p.Caps.ExecutorUSD,
224: 				}
225: 			}
226: 			plan.Phases = append(plan.Phases, phase)
227: 		}
228: 		v, err := c.PlanLoad(project, plan)
229: 		if err != nil {
230: 			return errorResult(err)
231: 		}
232: 		return jsonResult(v)
233: 	})
234: 
235: 	mcp.AddTool(s, &mcp.Tool{
236: 		Name:        "continue",
