17: // EventView is the compact view of one event log entry.
18: type EventView struct {
19: 	Seq            int64      `json:"seq"`
20: 	Dir            string     `json:"dir"`
21: 	Type           string     `json:"type"`
22: 	Subtype        string     `json:"subtype,omitempty"`
23: 	Text           string     `json:"text,omitempty"`
24: 	Tools          []string   `json:"tools,omitempty"`
25: 	CostUSD        float64    `json:"cost_usd,omitempty"`
26: 	TerminalReason string     `json:"terminal_reason,omitempty"`
27: 	Exit           *EventExit `json:"exit,omitempty"`
28: }
