36: // Cut returns s when it holds at most max runes, and otherwise its first max
37: // runes followed by one U+2026. A max <= 0 means 200.
38: func Cut(s string, max int) string {
39: 	if max <= 0 {
40: 		max = 200
41: 	}
42: 	count := 0
43: 	for i := range s {
44: 		if count == max {
45: 			return s[:i] + "…"
46: 		}
47: 		count++
48: 	}
49: 	return s
50: }
51: 
52: // View turns one event log entry into its compact view.
53: func View(e eventlog.Entry, max int) EventView {
54: 	v := EventView{Seq: e.Seq, Dir: e.Dir}
55: 
56: 	if e.Dir == "exit" {
57: 		v.Type = "exit"
58: 		var payload EventExit
59: 		if err := json.Unmarshal(e.Msg, &payload); err == nil {
60: 			v.Exit = &EventExit{Code: payload.Code, Stderr: Cut(payload.Stderr, max)}
61: 		}
62: 		return v
63: 	}
64: 
65: 	ev, err := stream.Parse(e.Msg)
66: 	if err != nil {
67: 		v.Type = "raw"
68: 		var s string
69: 		if json.Unmarshal(e.Msg, &s) == nil {
70: 			v.Text = Cut(s, max)
71: 		} else {
72: 			v.Text = Cut(string(e.Msg), max)
73: 		}
74: 		return v
75: 	}
76: 
77: 	v.Type = ev.Type
78: 	v.Subtype = ev.Subtype
79: 
80: 	switch ev.Type {
81: 	case "assistant":
82: 		v.Text = Cut(ev.Text, max)
83: 		v.Tools = assistantTools(ev)
84: 	case "user":
85: 		decodeUser(ev, &v, max)
86: 	case "result":
87: 		v.Text = Cut(ev.Text, max)
88: 		if ev.Result != nil {
89: 			v.CostUSD = ev.Result.TotalCostUSD
90: 			v.TerminalReason = ev.Result.TerminalReason
91: 		}
92: 	case "rate_limit_event":
93: 		if ev.Limits != nil {
94: 			v.Text = fmt.Sprintf("five_hour %d%% · seven_day %d%%",
95: 				Percent(ev.Limits.FiveHour.Utilization),
96: 				Percent(ev.Limits.SevenDay.Utilization))
97: 		}
98: 	case "control_request":
99: 		if ev.Subtype == "can_use_tool" {
100: 			v.Tools = []string{ev.Tool}
101: 			if ev.Question != nil {
102: 				v.Text = Cut(ev.Question.Text, max)
103: 			}
104: 		}
105: 	}
106: 	return v
107: }
108: 
109: // Views maps a window of entries to their views. It returns a non-nil, empty
110: // Events slice when there are none.
111: func Views(e Events, max int) EventsView {
112: 	out := EventsView{Events: []EventView{}, Last: e.Last}
113: 	for _, entry := range e.Entries {
114: 		out.Events = append(out.Events, View(entry, max))
115: 	}
116: 	return out
117: }
