119: // assistantTools returns the names of message.content elements of type
120: // tool_use, or nil when there are none.
121: func assistantTools(ev stream.Event) []string {
122: 	var top map[string]json.RawMessage
123: 	if json.Unmarshal(ev.Raw, &top) != nil {
124: 		return nil
125: 	}
126: 	msgRaw, ok := top["message"]
127: 	if !ok {
128: 		return nil
129: 	}
130: 	var msg map[string]json.RawMessage
131: 	if json.Unmarshal(msgRaw, &msg) != nil {
132: 		return nil
133: 	}
134: 	cRaw, ok := msg["content"]
135: 	if !ok {
136: 		return nil
137: 	}
138: 	var parts []json.RawMessage
139: 	if json.Unmarshal(cRaw, &parts) != nil {
140: 		return nil
141: 	}
142: 	var tools []string
143: 	for _, p := range parts {
144: 		var pm map[string]json.RawMessage
145: 		if json.Unmarshal(p, &pm) != nil {
146: 			continue
147: 		}
148: 		var pt string
149: 		if json.Unmarshal(pm["type"], &pt) != nil || pt != "tool_use" {
150: 			continue
151: 		}
152: 		var name string
153: 		if json.Unmarshal(pm["name"], &name) == nil {
154: 			tools = append(tools, name)
155: 		}
156: 	}
157: 	if len(tools) == 0 {
158: 		return nil
159: 	}
160: 	return tools
161: }
162: 
163: // decodeUser fills Text and Subtype from a "user" event's message.content:
164: // a JSON string is used as-is; an array takes the first element's type as
165: // Subtype and, when that type is "text", its text as Text.
166: func decodeUser(ev stream.Event, v *EventView, max int) {
167: 	var top map[string]json.RawMessage
168: 	if json.Unmarshal(ev.Raw, &top) != nil {
169: 		return
170: 	}
171: 	msgRaw, ok := top["message"]
172: 	if !ok {
173: 		return
174: 	}
175: 	var msg map[string]json.RawMessage
176: 	if json.Unmarshal(msgRaw, &msg) != nil {
177: 		return
178: 	}
179: 	cRaw, ok := msg["content"]
180: 	if !ok {
181: 		return
182: 	}
183: 	var s string
184: 	if json.Unmarshal(cRaw, &s) == nil {
185: 		v.Text = Cut(s, max)
186: 		return
187: 	}
188: 	var parts []json.RawMessage
189: 	if json.Unmarshal(cRaw, &parts) != nil || len(parts) == 0 {
190: 		return
191: 	}
192: 	var pm map[string]json.RawMessage
193: 	if json.Unmarshal(parts[0], &pm) != nil {
194: 		return
195: 	}
196: 	var pt string
197: 	if json.Unmarshal(pm["type"], &pt) != nil {
198: 		return
199: 	}
200: 	v.Subtype = pt
201: 	if pt == "text" {
202: 		var tx string
203: 		if json.Unmarshal(pm["text"], &tx) == nil {
204: 			v.Text = Cut(tx, max)
205: 		}
206: 	}
207: }

