559: // Tick drives the clocked checks and starts queued projects.
560: func (d *Daemon) Tick(ctx context.Context) {
561: 	d.mu.Lock()
562: 	defer d.mu.Unlock()
563: 	names := d.names()
564: 	for _, name := range names {
565: 		p := d.projects[name]
566: 		acts := p.state.Loop.Tick(d.deps.Now(), d.deps.Config.Loop)
567: 		if len(acts) > 0 {
568: 			d.execute(ctx, name, acts)
569: 		}
570: 	}
571: 	for d.runningCount() < d.deps.Config.MaxParallel {
572: 		best := ""
573: 		var bestAt time.Time
574: 		for _, name := range names {
575: 			p := d.projects[name]
576: 			if p.state.Loop.State == "idle" && p.state.Loop.Queue.State == "queued" {
577: 				if best == "" || p.queuedAt.Before(bestAt) {
578: 					best = name
579: 					bestAt = p.queuedAt
580: 				}
581: 			}
582: 		}
583: 		if best == "" {
584: 			break
585: 		}
586: 		p := d.projects[best]
587: 		acts, err := p.state.Loop.Begin(d.deps.Now())
588: 		if err != nil {
589: 			break
590: 		}
591: 		d.execute(ctx, best, acts)
592: 	}
593: }
