611: func (d *Daemon) executeAction(ctx context.Context, p *proj, project string, act supervisor.Action) bool {
612: 	switch act.Kind {
613: 	case "start_check":
614: 		start := gitrules.StartCheck(ctx, d.deps.Runner, p.reg.Dir)
615: 		d.execute(ctx, project, p.state.Loop.StartChecked(start, d.deps.NewID, d.deps.Now()))
616: 	case "spawn":
617: 		if !d.spawnSession(ctx, p, project, act) {
618: 			return false
619: 		}
620: 	case "first_line", "write":
621: 		d.orderLine(project, act.Line)
622: 	case "end_check":
623: 		end := gitrules.EndCheck(ctx, d.deps.Runner, p.reg.Dir, p.state.Loop.Phase)
624: 		d.execute(ctx, project, p.state.Loop.EndChecked(end, d.deps.Now()))
625: 	case "kill":
626: 		if p.proc != nil {
627: 			_ = p.proc.Kill()
628: 		}
629: 	case "post":
630: 		if d.deps.Post != nil {
631: 			_, _ = d.deps.Post(ctx, project, act.Milestone.Kind, act.Milestone.Headline, act.Milestone.Numbers)
632: 		}
633: 	}
634: 	return true
635: }
