637: func (d *Daemon) spawnSession(ctx context.Context, p *proj, project string, act supervisor.Action) bool {
638: 	if p.proc != nil {
639: 		_ = p.proc.Kill()
640: 		p.proc = nil
641: 	}
642: 	fail := func(err error) bool {
643: 		d.execute(ctx, project, p.state.Loop.Exited(-3, err.Error(), d.deps.Now(), d.deps.Config.Loop))
644: 		return false
645: 	}
646: 	token := d.deps.NewID()
647: 	if err := d.deps.Registry.PutSecret(project, "session-token", token); err != nil {
648: 		return fail(err)
649: 	}
650: 	base := d.deps.Registry.Base()
651: 	dir := filepath.Join(base, project)
652: 	mcpPath, err := claude.WriteMCPConfig(dir, "morphd", d.deps.Config.MCPBaseURL+"/mcp/"+project+"/session", token)
653: 	if err != nil {
654: 		return fail(err)
655: 	}
656: 	logPath := filepath.Join(dir, "sessions", act.SessionID+".jsonl")
657: 	log, err := eventlog.Open(logPath)
658: 	if err != nil {
659: 		return fail(err)
660: 	}
661: 	proc, err := d.deps.Spawn(ctx, claude.Launch{
662: 		Bin:           d.deps.Config.ClaudeBin,
663: 		Dir:           p.reg.Dir,
664: 		SessionID:     act.SessionID,
665: 		Resume:        act.Resume,
666: 		BudgetUSD:     act.BudgetUSD,
667: 		Model:         d.deps.Config.Model,
668: 		MCPConfigPath: mcpPath,
669: 		Extra:         d.deps.Config.ExtraArgs,
670: 	})
671: 	if err != nil {
672: 		return fail(err)
673: 	}
674: 	p.machine = session.New()
675: 	p.proc = proc
676: 	p.log = log
677: 	if startPump != nil {
678: 		startPump(d, ctx, project, proc, log)
679: 	}
680: 	return true
681: }
