43: // pumpLine folds one stdout line into the process's log, the session machine
44: // and the loop. The whole handling runs under d.mu so a caller that observes
45: // the line through Events also observes its effects.
46: func (d *Daemon) pumpLine(ctx context.Context, project string, p claude.Process, l *eventlog.Log, line []byte) {
47: 	d.mu.Lock()
48: 	defer d.mu.Unlock()
49: 
50: 	pr := d.projects[project]
51: 	if pr == nil {
52: 		return
53: 	}
54: 	now := d.deps.Now()
55: 
56: 	msg := json.RawMessage(line)
57: 	if !json.Valid(line) {
58: 		b, err := json.Marshal(string(line))
59: 		if err != nil {
60: 			return
61: 		}
62: 		msg = json.RawMessage(b)
63: 	}
64: 	_, _ = l.Append("out", msg, now)
65: 
66: 	ev, err := stream.Parse(line)
67: 	if err != nil {
68: 		return
69: 	}
70: 	if pr.proc != p {
71: 		return
72: 	}
73: 	pr.state.Loop.Event(now)
74: 	if pr.machine == nil {
75: 		return
76: 	}
77: 	macts := pr.machine.Apply(ev, now)
78: 
79: 	var lacts []supervisor.Action
80: 	switch ev.Type {
81: 	case "result":
82: 		if ev.Result != nil {
83: 			lacts = pr.state.Loop.Turn(*ev.Result, now, d.deps.Config.Loop)
84: 		}
85: 	case "rate_limit_event":
86: 		if ev.Limits != nil {
87: 			lacts = pr.state.Loop.Limits(*ev.Limits, now, d.deps.Config.Loop)
88: 		}
89: 	}
90: 
91: 	for _, a := range macts {
92: 		switch a.Kind {
93: 		case "write":
94: 			d.writeLine(project, a.Line)
95: 		case "ask":
96: 			if d.deps.Post != nil {
97: 				_, _ = d.deps.Post(ctx, project, "ask", a.Headline, a.Numbers)
98: 			}
99: 		case "turn":
100: 			headline := a.Headline
101: 			if headline == "" {
102: 				headline = "(no text)"
103: 			} else {
104: 				headline = truncateRunes(headline, 200)
105: 			}
106: 			if d.deps.Post != nil {
107: 				_, _ = d.deps.Post(ctx, project, "idle", pr.state.Loop.Phase+" turn ended: "+headline, a.Numbers)
108: 			}
109: 		case "limit":
110: 			// nothing
111: 		}
112: 	}
113: 	d.execute(ctx, project, lacts)
114: }
