141: // Wait blocks until every pump of project whose process is no longer current
142: // has returned. It returns immediately when there is none.
143: func (d *Daemon) Wait(project string) {
144: 	d.mu.Lock()
145: 	pr := d.projects[project]
146: 	var dones []chan struct{}
147: 	if pr != nil {
148: 		for proc, done := range pr.pumps {
149: 			if proc != pr.proc {
150: 				dones = append(dones, done)
151: 			}
152: 		}
153: 	}
154: 	d.mu.Unlock()
155: 	for _, done := range dones {
156: 		<-done
157: 	}
158: }
