160: // stderrTail returns the last 20 lines of stderr, after trimming one trailing
161: // newline, or "" when stderr is empty.
162: func stderrTail(stderr string) string {
163: 	if stderr == "" {
164: 		return ""
165: 	}
166: 	stderr = strings.TrimSuffix(stderr, "\n")
167: 	lines := strings.Split(stderr, "\n")
168: 	if len(lines) > 20 {
169: 		lines = lines[len(lines)-20:]
170: 	}
171: 	return strings.Join(lines, "\n")
172: }
173: 
174: // truncateRunes returns s cut to at most n runes.
175: func truncateRunes(s string, n int) string {
176: 	r := []rune(s)
177: 	if len(r) <= n {
178: 		return s
179: 	}
180: 	return string(r[:n])
181: }

